import { expect, test } from "bun:test";
import { glanceOf, paintGlance } from "../src/glance.ts";
import { fakeApp } from "./guard.ts";

test("an ask answered elsewhere goes once hello is back", () => {
  const app = fakeApp({ asks: ["d1", "d2"] });
  paintGlance(app, glanceOf(app.S));
  app.hello({ answered: ["d1"] });
  expect(app.S.openDecisions().map((d) => d.id)).toEqual(["d2"]);
});

